using System;using System.Linq;using System.Drawing;using System.Reflection;using System.Windows.Forms;
class SubtitleLayoutChecks {
 [STAThread]static void Main(){try{Run();}catch(Exception ex){while(ex.InnerException!=null)ex=ex.InnerException;Console.WriteLine("FAIL "+ex.GetType().Name+": "+ex.Message);Environment.ExitCode=1;}}static void Run(){var f=BindingFlags.Instance|BindingFlags.NonPublic;int checkedLines=0;float minFont=100;using(var game=new Game()){game.Show();var t=typeof(Game);var chapters=(System.Collections.Generic.List<Chapter>)t.GetField("chapters",f).GetValue(game);var save=(Save)t.GetField("save",f).GetValue(game);t.GetField("developerMode",f).SetValue(game,true);save.english=save.chinese=true;t.GetField("translating",f).SetValue(game,true);t.GetField("englishVisible",f).SetValue(game,true);
 foreach(var size in new[]{new Size(800,500),new Size(1280,780),new Size(1920,1080)}){game.Size=size;Application.DoEvents();int fixedHeight=-1;foreach(var c in chapters){t.GetField("current",f).SetValue(game,c);save.sectionAttempts[c.id]=new SectionAttempt{review=true,introShown=true};t.GetField("index",f).SetValue(game,0);t.GetMethod("ShowStory",f).Invoke(game,null);var stage=(ArtPanel)t.GetField("stage",f).GetValue(game);var panel=(Control)t.GetField("dialogue",f).GetValue(game);if(panel==null)continue;Application.DoEvents();if(fixedHeight<0)fixedHeight=panel.Height;if(panel.Height!=fixedHeight)throw new Exception("chapter-dependent height");for(int i=0;i<c.lines.Count;i++){t.GetField("index",f).SetValue(game,i);t.GetMethod("UpdateLine",f).Invoke(game,null);Application.DoEvents();var en=(SentenceView)t.GetField("englishText",f).GetValue(game);var zh=(Control)t.GetField("translationLabel",f).GetValue(game);if(panel.Height!=fixedHeight)throw new Exception("line-dependent height");if(8+en.WrappedLineCount(en.Width-22)*(int)Math.Ceiling(en.Font.Height*1.55)>en.Height)throw new Exception(c.id+" English clipped "+i);if(TextRenderer.MeasureText(zh.Text,zh.Font,new Size(zh.Width-5,int.MaxValue),TextFormatFlags.NoPadding|TextFormatFlags.WordBreak).Height+4>zh.Height)throw new Exception(c.id+" Chinese clipped "+i);minFont=Math.Min(minFont,Math.Min(en.Font.Size,zh.Font.Size));checkedLines++;}var geometry=new SubtitleLayout(stage.Width,stage.Height);if(geometry.Height!=panel.Height)throw new Exception("CG geometry mismatch");}Console.WriteLine("Fixed height at "+size+": "+fixedHeight);}
 }Console.WriteLine("PASS "+checkedLines+" dialogue layouts at 3 sizes; no clipping or height changes; minimum font "+minFont);}
}

